namespace sv_52e6a0d41fa04538a6fc8dc809581f81.Services;

/// <summary>
/// Scoped service (per circuit) that holds the latest low-stock alert count
/// and notifies all subscribed components when it changes.
/// </summary>
public class InventoryAlertService
{
    private static readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired whenever <see cref="CurrentAlertCount"/> is updated.
    /// Components must subscribe via InvokeAsync(StateHasChanged) because
    /// the call may originate from a timer (background thread).
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Simulates a database query that returns the number of items
    /// below minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Fetches a new alert count and notifies all subscribers.
    /// Called by whichever component owns the polling loop.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }
}

