@page "/dashboard"
@rendermode InteractiveServer
@using sv_52e6a0d41fa04538a6fc8dc809581f81.Services
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<p>Currently viewing: <strong>@CurrentWarehouse?.Name</strong></p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body d-flex align-items-center justify-content-between">
        <div>
            <h5 class="card-title mb-0">Low-Stock Alerts</h5>
            <small class="text-muted">Refreshes every 10 s</small>
        </div>
        @if (AlertService.CurrentAlertCount > 0)
        {
            <span class="badge bg-danger fs-5">@AlertService.CurrentAlertCount</span>
        }
        else
        {
            <span class="badge bg-success fs-5">0</span>
        }
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? CurrentWarehouse { get; set; }

    private CancellationTokenSource? _cts;
    private Action? _handler;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to alert changes so the dashboard re-renders when
        // the service is updated (including from the polling loop below).
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;

        // Initial fetch before the first timer tick.
        if (CurrentWarehouse is not null)
        {
            await AlertService.RefreshAsync(CurrentWarehouse.Id);
        }

        StartPolling();
    }

    protected override async Task OnParametersSetAsync()
    {
        // Warehouse changed via the cascading value — restart polling for the new site.
        StopPolling();

        if (CurrentWarehouse is not null)
        {
            await AlertService.RefreshAsync(CurrentWarehouse.Id);
        }

        StartPolling();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            while (await timer.WaitForNextTickAsync(token))
            {
                if (CurrentWarehouse is not null)
                {
                    await AlertService.RefreshAsync(CurrentWarehouse.Id);
                }
            }
        }, token);
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        StopPolling();
    }
}

